-- rowstile 0.1.0-dev: break_glass_over_a_share. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '4e27b47b23ae4b43', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '4e27b47b23ae4b43' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '4e27b47b23ae4b43' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '4e27b47b23ae4b43' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '7fb4ab8320424053' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '7fb4ab8320424053', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'hd_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('team__parent__tree', ARRAY[to_regclass('"hd"."teams"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"hd"."teams"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."team__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

-- Emergency access: people who hold 'break_glass' on an object give themselves a relation on it
-- for a short time (one day at most); it is audited and announced on channel authz_alerts
-- (the notification carries the audit row's id; the details stay in authz.audit)
CREATE OR REPLACE FUNCTION authz.break_glass(p_type text, p_id text, p_relation text, p_reason text,
  p_duration interval DEFAULT interval '1 hour') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE g authz.shares; v_until timestamptz; v_audit bigint; v_held boolean; v_rel authz_int.shared_relations;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.break_glass');
  IF coalesce(btrim(p_reason), '') = '' THEN RAISE EXCEPTION 'say why (it is kept in the audit trail)' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710'; END IF;
  IF p_duration IS NULL OR p_duration <= interval '0' OR p_duration > interval '1 day' THEN
    RAISE EXCEPTION 'emergency access lasts more than nothing and one day at most' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  -- the object and the user are locked (FOR KEY SHARE), as authz.share locks them: a delete waits for this, or this
  -- for it and then finds nothing to break into
  v_held := authz.uid() IS NOT NULL;
  IF v_held THEN v_held := authz_int.hold(p_type, p_id); END IF;
  IF v_held THEN v_held := authz_int.hold('user', authz.uid()::text); END IF;
  IF NOT v_held
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'break_glass')
     OR NOT authz.can(p_type, p_id, 'break_glass') THEN
    RAISE EXCEPTION 'you cannot break the glass on % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  SELECT * INTO v_rel FROM authz_int.shared_relations
  WHERE object_type = p_type AND relation = p_relation AND subject = 'user';
  IF v_rel.relation IS NULL THEN
    RAISE EXCEPTION 'the policy does not allow sharing %.% with a user', p_type, p_relation USING HINT = 'rowstile help AZ706';
  END IF;
  -- the relation's `shared if` holds for whoever breaks the glass, as authz.share asks it of any share
  IF NOT authz_int.share_if(p_type || '.' || p_relation || '.user', p_id, 'user', authz.uid()::text, '') THEN
    RAISE EXCEPTION 'the policy does not allow you %.% on % %, even to break the glass (%)', p_type, p_relation, p_type, p_id,
      coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  v_until := now() + p_duration;
  PERFORM set_config('authz_ctx.reason', p_reason, true);
  PERFORM authz_int.mark_row(p_type, p_id);
  PERFORM authz_int.mark_row('user', authz.uid()::text);
  SELECT * INTO g FROM authz.shares WHERE object_type = p_type AND object_id = p_id AND relation = p_relation
    AND subject_type = 'user' AND subject_id = authz.uid()::text AND subject_relation = '' FOR UPDATE;
  IF g.object_id IS NULL THEN
    INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                              expires_at, created_by)
    VALUES (p_type, p_id, p_relation, 'user', authz.uid()::text, '', v_until, authz_int.actor());
  ELSIF (g.expires_at IS NULL OR g.expires_at > now())
        AND (g.caveat IS NOT NULL OR (g.starts_at IS NOT NULL AND g.starts_at > now())) THEN
    -- a share of theirs that starts later or holds while a caveat does: the emergency access would replace it (one
    -- share a subject and relation on an object), and it would be gone when that ends; its manager decides instead
    RAISE EXCEPTION 'a share of yours gives you %.% on % % %, and breaking the glass would replace it', p_type, p_relation,
      p_type, p_id, concat_ws(' ', CASE WHEN g.starts_at > now() THEN 'from ' || g.starts_at END,
                              CASE WHEN g.caveat IS NOT NULL THEN 'while caveat ' || g.caveat || ' holds' END)
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ717';
  ELSIF g.expires_at IS NOT NULL AND g.expires_at < v_until THEN
    -- one that ends sooner, or has ended, lasts until then, unconditionally (the old one is in the audit)
    UPDATE authz.shares SET expires_at = v_until, starts_at = NULL, caveat = NULL, caveat_args = NULL
    WHERE object_type = p_type AND object_id = p_id AND relation = p_relation
      AND subject_type = 'user' AND subject_id = authz.uid()::text AND subject_relation = '';
  END IF;
  PERFORM authz_int.audit('break_glass', p_type, p_id, p_relation, 'user', authz.uid()::text, '',
                          jsonb_build_object('until', v_until, 'previous_share', CASE WHEN g.object_id IS NULL THEN NULL
                                             ELSE to_jsonb(g) - 'subject_id' END));
  SELECT max(id) INTO v_audit FROM authz.audit WHERE action = 'break_glass' AND txid = txid_current();
  PERFORM pg_notify('authz_alerts', json_build_object('audit_id', v_audit, 'action', 'break_glass')::text);
END $f$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

-- The sync role reads the index, and nothing else rowstile keeps
DO $sr$
DECLARE v_sync oid := to_regrole('"hd_electric"'); v_app oid := to_regrole('"hd_app"'); v_cols text;
BEGIN
  IF v_sync IS NULL THEN
    RAISE EXCEPTION 'the sync role hd_electric does not exist [AZ808]'
      USING HINT = 'make it for the engine: CREATE ROLE hd_electric LOGIN REPLICATION BYPASSRLS, then apply again';
  END IF;
  IF pg_catalog.pg_has_role(v_sync, CURRENT_USER, 'MEMBER') THEN
    RAISE EXCEPTION 'the sync role hd_electric is the role that applies the policy (%), or a member of it [AZ808]', CURRENT_USER
      USING HINT = 'the engine connects as a role of its own, which owns nothing of the database';
  END IF;
  IF v_app IS NOT NULL AND (pg_catalog.pg_has_role(v_sync, v_app, 'MEMBER') OR pg_catalog.pg_has_role(v_app, v_sync, 'MEMBER')) THEN
    RAISE EXCEPTION 'the sync role hd_electric and the app role hd_app are one another''s members: the app would read every row [AZ808]'
      USING HINT = 'the engine connects as a role of its own, which the app role is not a member of, nor it of the app role';
  END IF;
  SELECT pg_catalog.string_agg(m.tbl || '.' || m.col, ', ' ORDER BY m.tbl, m.col) INTO v_cols FROM authz_int.masked_columns m
  WHERE pg_catalog.has_column_privilege(v_sync, m.tbl, m.col, 'SELECT');
  IF v_cols IS NOT NULL THEN
    RAISE EXCEPTION 'the sync role hd_electric may read masked columns: % [AZ809]', v_cols
      USING HINT = 'it reads every row, so a masked column would reach every client: revoke SELECT on the table, grant the other columns (GRANT SELECT (id, name) ON ...), then apply again';
  END IF;
END $sr$;
GRANT USAGE ON SCHEMA authz_sync TO "hd_electric";
GRANT SELECT ON ALL TABLES IN SCHEMA authz_sync TO "hd_electric";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."customer_org__member"', 'authz_int."customer_org__view"', 'authz_int."team__lead"', 'authz_int."team__manage"', 'authz_int."team__member"', 'authz_int."team__oversee"', 'authz_int."team__view"', 'authz_int."ticket__cc"', 'authz_int."ticket__reply"', 'authz_int."ticket__responder"', 'authz_int."ticket__roles:work"', 'authz_int."ticket__view"', 'authz_int."ticket__work"', 'authz_int."user__org_tickets"', 'authz_int."user__self"', 'authz_int."workspace__admin"', 'authz_int."workspace__agent"', 'authz_int."workspace__connected"', 'authz_int."workspace__manage"', 'authz_int."workspace__member"', 'authz_int."workspace__view"', 'authz_int."workspace__work"', 'authz_int."workspace__work_all"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"hd_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"hd_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"hd.comments:delete:items"', '"hd.comments:delete:why"', '"hd.comments:insert:items"', '"hd.comments:insert:refuse"', '"hd.comments:insert:why"', '"hd.comments:rules:explain"', '"hd.comments:update:items"', '"hd.comments:update:refuse"', '"hd.comments:update:why"', '"hd.customer_orgs:column id, workspace_id:items"', '"hd.customer_orgs:column id, workspace_id:why"', '"hd.customer_orgs:delete:items"', '"hd.customer_orgs:delete:why"', '"hd.customer_orgs:insert:items"', '"hd.customer_orgs:insert:refuse"', '"hd.customer_orgs:insert:why"', '"hd.customer_orgs:rules:explain"', '"hd.customer_orgs:update:items"', '"hd.customer_orgs:update:refuse"', '"hd.customer_orgs:update:why"', '"hd.integrations:column id, workspace_id:items"', '"hd.integrations:column id, workspace_id:why"', '"hd.integrations:delete:items"', '"hd.integrations:delete:why"', '"hd.integrations:insert:items"', '"hd.integrations:insert:refuse"', '"hd.integrations:insert:why"', '"hd.integrations:rules:explain"', '"hd.integrations:update:items"', '"hd.integrations:update:refuse"', '"hd.integrations:update:why"', '"hd.support_access:delete:items"', '"hd.support_access:delete:why"', '"hd.support_access:insert:items"', '"hd.support_access:insert:refuse"', '"hd.support_access:insert:why"', '"hd.support_access:rules:explain"', '"hd.support_access:update:items"', '"hd.support_access:update:refuse"', '"hd.support_access:update:why"', '"hd.team_leads:delete:items"', '"hd.team_leads:delete:why"', '"hd.team_leads:insert:items"', '"hd.team_leads:insert:refuse"', '"hd.team_leads:insert:why"', '"hd.team_leads:rules:explain"', '"hd.team_leads:update:items"', '"hd.team_leads:update:refuse"', '"hd.team_leads:update:why"', '"hd.team_members:delete:items"', '"hd.team_members:delete:why"', '"hd.team_members:insert:items"', '"hd.team_members:insert:refuse"', '"hd.team_members:insert:why"', '"hd.team_members:rules:explain"', '"hd.team_members:update:items"', '"hd.team_members:update:refuse"', '"hd.team_members:update:why"', '"hd.teams:column id, workspace_id:items"', '"hd.teams:column id, workspace_id:why"', '"hd.teams:column parent_id after:items"', '"hd.teams:column parent_id after:why"', '"hd.teams:delete:items"', '"hd.teams:delete:why"', '"hd.teams:insert:items"', '"hd.teams:insert:refuse"', '"hd.teams:insert:why"', '"hd.teams:rules:explain"', '"hd.teams:update:items"', '"hd.teams:update:refuse"', '"hd.teams:update:why"', '"hd.tickets:column id, workspace_id, requester_id:items"', '"hd.tickets:column id, workspace_id, requester_id:why"', '"hd.tickets:column status after:items"', '"hd.tickets:column status after:why"', '"hd.tickets:column status:items"', '"hd.tickets:column status:why"', '"hd.tickets:column subject:items"', '"hd.tickets:column subject:why"', '"hd.tickets:column team_id after:items"', '"hd.tickets:column team_id after:why"', '"hd.tickets:column team_id, assignee_id:items"', '"hd.tickets:column team_id, assignee_id:why"', '"hd.tickets:delete:items"', '"hd.tickets:delete:why"', '"hd.tickets:insert:items"', '"hd.tickets:insert:refuse"', '"hd.tickets:insert:why"', '"hd.tickets:rules:explain"', '"hd.tickets:update:items"', '"hd.tickets:update:refuse"', '"hd.tickets:update:why"', '"hd.tickets:update_after:items"', '"hd.tickets:update_after:refuse"', '"hd.tickets:update_after:why"', '"hd.users:column customer_org_id after:items"', '"hd.users:column customer_org_id after:why"', '"hd.users:column customer_org_id:items"', '"hd.users:column customer_org_id:why"', '"hd.users:column id, workspace_id, kind:items"', '"hd.users:column id, workspace_id, kind:why"', '"hd.users:column notes:items"', '"hd.users:column notes:why"', '"hd.users:column role, active:items"', '"hd.users:column role, active:why"', '"hd.users:insert:items"', '"hd.users:insert:refuse"', '"hd.users:insert:why"', '"hd.users:rules:explain"', '"hd.users:update:items"', '"hd.users:update:refuse"', '"hd.users:update:why"', '"hd.workspaces:column id:ite